268	    /**
269	     * Validates an owner's postcode against the region derived from its city. The postcode is
270	     * optional: a {@code null} value is always accepted. When present it must fall within the
271	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
272	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
273	     * The 4-digit syntax itself is enforced upstream by bean validation.
274	     *
275	     * @param postcode the owner's postcode (may be {@code null})
276	     * @param locality the region derived from the owner's city
277	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
278	     *         within the region's range; {@code false} when it is out of range
279	     */
280	    private boolean isPostcodeValidForCity(String postcode, String locality) {
281	        if (postcode == null) {
282	            return true;
283	        }
284	        int[] range = REGION_POSTCODES.get(locality);
285	        if (range == null) {
286	            return true;
287	        }
288	        int value = Integer.parseInt(postcode);
289	        return value >= range[0] && value <= range[1];
290	    }
291	
292	    /**
293	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
294	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
295	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
296	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
297	     * recognised country codes the national number (the digits after the country code) must also be
298	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
299	     * needs 10); a wrong national-number length yields {@code null}.
300	     *
301	     * @param telephone the raw telephone value (may be {@code null})
302	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
303	     *         a valid E.164 number
304	     */
305	    private String toE164(String telephone) {
306	        if (telephone == null) {
307	            return null;
308	        }
309	        String trimmed = telephone.trim();
310	        boolean hasCountryCode = trimmed.startsWith("+");
311	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
312	        if (hasCountryCode) {
313	            cleaned = cleaned.substring(1);
314	        }
315	        if (!cleaned.matches("[0-9]+")) {
316	            return null;
317	        }
318	        String digits;
319	        if (hasCountryCode) {
320	            digits = cleaned;
321	        } else {
322	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
323	            digits = "61" + national;
324	        }
325	        if (digits.length() < 8 || digits.length() > 15) {
326	            return null;
327	        }
328	        if (!hasValidNationalNumberLength(digits)) {
329	            return null;
330	        }
331	        return "+" + digits;
332	    }
333	
334	    /**
335	     * Checks the national-number length of an E.164 digit string (country code plus national
336	     * number, without the leading {@code '+'}) against its country code. When the number's country
337	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
338	     * country code must number exactly what that country requires; the longest matching country
339	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
340	     * only by the generic total-length rule).
341	     *
342	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
343	     * @return {@code true} if the national-number length is acceptable for the country code
344	     */
345	    private boolean hasValidNationalNumberLength(String digits) {
346	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
347	            .filter(entry -> digits.startsWith(entry.getKey()))
348	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
349	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
350	            .orElse(true);
351	    }
352	
353	    /**
354	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
355	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
356	     *
357	     * @param email the raw email value (must not be {@code null})
358	     * @return the trimmed, lower-cased email
359	     */
360	    private String normalizeEmail(String email) {
361	        return email.trim().toLowerCase(Locale.ROOT);
362	    }
363	
364	    /**
365	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
366	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
367	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
368	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
369	     * normalized form, and every household comparison uses it.
370	     *
371	     * @param address the raw address value (may be {@code null})
372	     * @return the normalized address, or {@code null} if the input was {@code null}
373	     */
374	    private String normalizeAddress(String address) {
375	        if (address == null) {
376	            return null;
377	        }
378	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
379	        if (collapsed.isEmpty()) {
380	            return collapsed;
381	        }
382	        String[] tokens = collapsed.split(" ");
383	        StringBuilder sb = new StringBuilder(collapsed.length());
384	        for (int i = 0; i < tokens.length; i++) {
385	            if (i > 0) {
386	                sb.append(' ');
387	            }
388	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
389	        }
390	        return sb.toString();
391	    }
392	
393	    /**
394	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
395	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
396	     * so that owners are compared case-insensitively with collapsed whitespace.
397	     *
398	     * @param value the raw value (must not be {@code null})
399	     * @return the normalized comparison key
400	     */
401	    private String householdKey(String value) {
402	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
403	    }
404	
405	    /**
406	     * Derives a stable, shared household identifier for the owner's household. The value is a
407	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
408	     * every owner in the same household derives the identical identifier of the form
409	     * {@code 'HH-<12 upper-case hex>'}.
410	     *
411	     * @param owner the owner whose household identifier is derived
412	     * @return the stable household identifier
413	     */
414	    private String householdId(Owner owner) {
415	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
416	        try {
417	            byte[] digest = MessageDigest.getInstance("SHA-256")
418	                .digest(key.getBytes(StandardCharsets.UTF_8));
419	            StringBuilder sb = new StringBuilder(digest.length * 2);
420	            for (byte b : digest) {
421	                sb.append(String.format("%02x", b));
422	            }
423	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
424	        }
425	        catch (java.security.NoSuchAlgorithmException e) {
426	            throw new IllegalStateException("SHA-256 not available", e);
427	        }
428	    }
429	
430	    /**
431	     * Builds the customer code for a newly registered owner in the form
432	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
433	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
434	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
435	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
436	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Sequence numbers are not used,
437	     * so the code is a pure function of the owner's region and identity.
438	     *
439	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
440	     * @return the assigned customer code
441	     */
442	    private String customerCode(Owner owner) {
443	        String region = owner.getLocality();
444	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
445	        return region + "-" + hash8;
446	    }
447	
448	    /**
449	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
450	     * UTF-8 bytes of {@code input}.
451	     *
452	     * @param input  the value to hash
453	     * @param length the number of leading hex characters to keep
454	     * @return the truncated, upper-cased hex digest
455	     */
456	    private String sha256UpperHex(String input, int length) {
457	        try {
458	            byte[] digest = MessageDigest.getInstance("SHA-256")
459	                .digest(input.getBytes(StandardCharsets.UTF_8));
460	            StringBuilder sb = new StringBuilder(digest.length * 2);
461	            for (byte b : digest) {
462	                sb.append(String.format("%02x", b));
463	            }
464	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
465	        }
466	        catch (java.security.NoSuchAlgorithmException e) {
467	            throw new IllegalStateException("SHA-256 not available", e);
468	        }
469	    }
470	
471	    /**
472	     * Rolls a registration date forward onto a business day. When the given date falls on a
473	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
474	     *
475	     * @param date the effective registration date (must not be {@code null})
476	     * @return the same date if it is a weekday, otherwise the next Monday
477	     */
478	    private LocalDate toBusinessDay(LocalDate date) {
479	        DayOfWeek dayOfWeek = date.getDayOfWeek();
480	        if (dayOfWeek == DayOfWeek.SATURDAY) {
481	            return date.plusDays(2);
482	        }
483	        if (dayOfWeek == DayOfWeek.SUNDAY) {
484	            return date.plusDays(1);
485	        }
486	        return date;
487	    }
