489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Override
491	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
492	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
493	        if (currentOwner == null) {
494	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
495	        }
496	        String email = ownerFieldsDto.getEmail();
497	        if (email != null) {
498	            email = normalizeEmail(email);
499	            if (!EMAIL_PATTERN.matcher(email).matches()) {
500	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
501	            }
502	        }
503	        String telephone = toE164(ownerFieldsDto.getTelephone());
504	        if (telephone == null) {
505	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
506	        }
507	        currentOwner.setAddress(ownerFieldsDto.getAddress());
508	        currentOwner.setCity(ownerFieldsDto.getCity());
509	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
510	        currentOwner.setLastName(ownerFieldsDto.getLastName());
511	        currentOwner.setTelephone(telephone);
512	        currentOwner.setEmail(email);
513	        this.clinicService.saveOwner(currentOwner);
514	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
515	    }
