529	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
530	    @Override
531	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
532	        Owner owner = this.clinicService.findOwnerById(ownerId);
533	        if (owner == null) {
534	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	        }
536	        HttpHeaders headers = new HttpHeaders();
537	        Pet pet = petMapper.toPet(petFieldsDto);
