358	        String emailPart = this.email == null ? "" : this.email;
359	        String householdPart = this.householdId == null ? "" : this.householdId;
360	        return telephonePart + "|" + emailPart + "|" + householdPart;
361	    }
362	
363	    /**
364	     * City -> canonical region, the fixed ground truth for deriving locality.
365	     */
366	    private static final Map<String, String> CITY_REGION = Map.of(
367	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
368	
369	    /**
370	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
371	     * deriving locality from the postcode ahead of the city.
372	     */
373	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
374	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
375	
376	    /**
377	     * The owner's locality: the canonical region resolved by the postcode range first
378	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
379	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
380	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
381	     * when the city is not in the table either. The postcode takes precedence so cities that share a
382	     * name are disambiguated by their postcode's region.
383	     *
384	     * @return the canonical region string, or {@code "UNKNOWN"}
385	     */
386	    public String getLocality() {
387	        String byPostcode = regionForPostcode(this.postcode);
388	        if (byPostcode != null) {
389	            return byPostcode;
390	        }
391	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
392	    }
393	
394	    /**
395	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
396	     * absent, not a 4-digit number, or in no known range.
397	     *
398	     * @param postcode the owner's postcode (may be {@code null})
399	     * @return the matching region, or {@code null}
400	     */
401	    private static String regionForPostcode(String postcode) {
402	        if (postcode == null || !postcode.matches("\\d{4}")) {
403	            return null;
404	        }
405	        int value = Integer.parseInt(postcode);
406	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
407	            int[] range = entry.getValue();
408	            if (value >= range[0] && value <= range[1]) {
409	                return entry.getKey();
410	            }
411	        }
412	        return null;
413	    }
414	
415	    protected Set<Pet> getPetsInternal() {
416	        if (this.pets == null) {
417	            this.pets = new HashSet<>();
418	        }
419	        return this.pets;
420	    }
421	
422	    protected void setPetsInternal(Set<Pet> pets) {
423	        this.pets = pets;
424	    }
